/* Generated by Shinobi website generator. Plain JavaScript, no dependencies. */
(() => {
  "use strict";
  const doc = document;
  doc.documentElement.classList.remove("no-js");
  doc.documentElement.classList.add("js");

  const $ = (sel, root = doc) => root.querySelector(sel);
  const $$ = (sel, root = doc) => Array.from(root.querySelectorAll(sel));
  let CFG = {};
  try { CFG = JSON.parse($("#site-config").textContent); } catch (_) { CFG = {}; }
  // window.__navigate is a test seam; in normal use this just changes location.
  const navigate = (url) => (window.__navigate || ((u) => { window.location.href = u; }))(url);

  /* Images: swap to the bundled illustration if a photo cannot load. */
  const useFallback = (img) => {
    if (img.dataset.fallback && !img.dataset.fallbackUsed) {
      img.dataset.fallbackUsed = "1";
      img.src = img.dataset.fallback;
    }
  };
  doc.addEventListener("error", (e) => {
    if (e.target && e.target.tagName === "IMG") useFallback(e.target);
  }, true);
  $$("img[data-fallback]").forEach((img) => {
    if (img.complete && img.naturalWidth === 0) useFallback(img);
  });

  /* Header: mobile menu + scroll shadow */
  const header = $(".site-header");
  const toggle = $(".nav-toggle");
  const nav = $("#site-nav");
  const closeNav = () => { nav.classList.remove("is-open"); toggle.setAttribute("aria-expanded", "false"); };
  if (toggle && nav) {
    toggle.addEventListener("click", () => {
      const open = nav.classList.toggle("is-open");
      toggle.setAttribute("aria-expanded", String(open));
    });
    nav.addEventListener("click", (e) => { if (e.target.closest("a")) closeNav(); });
    doc.addEventListener("keydown", (e) => {
      if (e.key === "Escape" && nav.classList.contains("is-open")) { closeNav(); toggle.focus(); }
    });
  }
  if (header) {
    const onScroll = () => header.classList.toggle("is-scrolled", window.scrollY > 8);
    window.addEventListener("scroll", onScroll, { passive: true });
    onScroll();
  }

  /* Reveal on scroll */
  const reveals = $$(".reveal");
  if ("IntersectionObserver" in window) {
    const io = new IntersectionObserver((entries) => {
      entries.forEach((en) => { if (en.isIntersecting) { en.target.classList.add("is-visible"); io.unobserve(en.target); } });
    }, { threshold: 0.12 });
    reveals.forEach((el) => io.observe(el));
  } else {
    reveals.forEach((el) => el.classList.add("is-visible"));
  }

  /* Form helpers */
  const enc = encodeURIComponent;
  const setStatus = (form, state, msg) => {
    const el = $("[data-status]", form);
    el.dataset.state = state;
    el.textContent = msg;
  };
  const clearErrors = (form) => {
    $$("[data-error-for]", form).forEach((p) => { p.textContent = ""; });
    $$("[aria-invalid]", form).forEach((i) => i.removeAttribute("aria-invalid"));
  };
  const fail = (form, errors) => {
    let first = null;
    Object.entries(errors).forEach(([name, msg]) => {
      const holder = $(`[data-error-for="${name}"]`, form);
      if (holder) holder.textContent = msg;
      const input = form.elements[name];
      const target = input && input.length && input[0] ? input[0] : input;
      if (target && target.setAttribute) target.setAttribute("aria-invalid", "true");
      if (!first && target && target.focus) first = target;
    });
    setStatus(form, "error", "Please fix the highlighted fields and try again.");
    if (first) first.focus();
  };
  const emailOk = (v) => /^[^@\s]+@[^@\s]+\.[^@\s]{2,}$/.test(v);

  async function deliver(form, subject, fields) {
    const text = fields.map(([, label, value]) => `${label}: ${value}`).join("\n");
    const btn = $("button[type=submit]", form);
    const honey = form.elements["_gotcha"];
    if (honey && honey.value) { form.reset(); return; } // bot: pretend nothing happened
    if (CFG.delivery === "endpoint") {
      btn.disabled = true;
      setStatus(form, "ok", "Sending...");
      try {
        const payload = { _subject: subject, message: text };
        fields.forEach(([key, , value]) => { payload[key] = value; });
        const res = await fetch(CFG.endpoint, {
          method: "POST",
          headers: { "Content-Type": "application/json", "Accept": "application/json" },
          body: JSON.stringify(payload),
        });
        if (res.ok) {
          setStatus(form, "ok", "Thank you - your message was sent. We will get back to you soon.");
          form.reset();
          document.dispatchEvent(new CustomEvent("shinobi:sent"));
        } else {
          setStatus(form, "error", "Sorry, the message could not be sent (server error). Please try again or use the contact details on this page.");
        }
      } catch (_) {
        setStatus(form, "error", "Sorry, the message could not be sent (network error). Please try again or use the contact details on this page.");
      } finally {
        btn.disabled = false;
      }
    } else if (CFG.delivery === "email") {
      navigate(`mailto:${CFG.email}?subject=${enc(subject)}&body=${enc(text)}`);
      setStatus(form, "ok", `Your email app should now open with the message ready. Press Send there to deliver it. If nothing opened, email us at ${CFG.email}.`);
    } else if (CFG.delivery === "whatsapp") {
      navigate(`https://wa.me/${CFG.whatsapp}?text=${enc(subject + "\n\n" + text)}`);
      setStatus(form, "ok", "WhatsApp should now open with the message ready. Press Send there to deliver it.");
    } else {
      setStatus(form, "error", "This form is not connected yet, so nothing was sent. Please use the contact details on this page.");
    }
  }

  /* Products: search, category filter, enquiry list */
  const enquiry = new Map();
  const enquiryText = () => (enquiry.size
    ? "\n\nI am interested in:\n" + Array.from(enquiry.values()).map((p) => `- ${p.name}${p.price ? " (" + p.price + ")" : ""}`).join("\n")
    : "");
  const grid = $("#product-grid");
  const pill = $("#enquiry-pill");
  const listEl = $("#enquiry-list");
  const renderEnquiry = () => {
    if (pill) {
      pill.hidden = enquiry.size === 0;
      pill.textContent = `Enquiry list (${enquiry.size})`;
    }
    if (listEl) {
      listEl.textContent = "";
      enquiry.forEach((p, id) => {
        const li = doc.createElement("li");
        const span = doc.createElement("span");
        span.textContent = p.name;
        const rm = doc.createElement("button");
        rm.type = "button";
        rm.className = "btn btn--ghost btn--small";
        rm.textContent = "Remove";
        rm.setAttribute("aria-label", `Remove ${p.name} from enquiry list`);
        rm.addEventListener("click", () => toggleProduct(id));
        li.append(span, rm);
        listEl.append(li);
      });
      const wrap = $("#enquiry-wrap");
      if (wrap) wrap.hidden = enquiry.size === 0;
    }
  };
  function toggleProduct(id) {
    const card = $(`.product[data-id="${id}"]`);
    if (!card) return;
    const btn = $(".add-enquiry", card);
    if (enquiry.has(id)) {
      enquiry.delete(id);
      btn.setAttribute("aria-pressed", "false");
      btn.textContent = "Add to enquiry";
    } else {
      enquiry.set(id, { name: card.dataset.name, price: card.dataset.price || "" });
      btn.setAttribute("aria-pressed", "true");
      btn.textContent = "Added - remove";
    }
    renderEnquiry();
  }
  if (grid) {
    const cards = $$(".product", grid);
    const search = $("#product-search");
    const chips = $$(".chip");
    const count = $("#product-count");
    const empty = $("#product-empty");
    let category = "all";
    const apply = () => {
      const q = (search.value || "").trim().toLowerCase();
      let n = 0;
      cards.forEach((c) => {
        const hay = `${c.dataset.name} ${c.dataset.desc || ""} ${c.dataset.category || ""}`.toLowerCase();
        const ok = (category === "all" || c.dataset.category === category) && (!q || hay.includes(q));
        c.hidden = !ok;
        if (ok) n += 1;
      });
      count.textContent = `${n} of ${cards.length} shown`;
      empty.hidden = n !== 0;
    };
    search.addEventListener("input", apply);
    chips.forEach((chip) => chip.addEventListener("click", () => {
      category = chip.dataset.category;
      chips.forEach((c) => c.setAttribute("aria-pressed", String(c === chip)));
      apply();
    }));
    cards.forEach((c) => $(".add-enquiry", c).addEventListener("click", () => toggleProduct(c.dataset.id)));
    apply();
    document.addEventListener("shinobi:sent", () => { enquiry.clear(); cards.forEach((c) => { const b = $(".add-enquiry", c); b.setAttribute("aria-pressed", "false"); b.textContent = "Add to enquiry"; }); renderEnquiry(); });
  }

  /* Contact form */
  const cf = $("#contact-form");
  if (cf) {
    cf.addEventListener("submit", (e) => {
      e.preventDefault();
      clearErrors(cf);
      const v = (n) => (cf.elements[n].value || "").trim();
      const errors = {};
      if (v("name").length < 2) errors.name = "Please enter your name.";
      if (!emailOk(v("email"))) errors.email = "Please enter a valid email address.";
      if (v("message").length < 5 && enquiry.size === 0) errors.message = "Please write a short message (at least 5 characters).";
      if (Object.keys(errors).length) return fail(cf, errors);
      const fields = [["name", "Name", v("name")], ["email", "Email", v("email")]];
      if (v("phone")) fields.push(["phone", "Phone", v("phone")]);
      fields.push(["details", "Message", (v("message") || "(see enquiry list)") + enquiryText()]);
      deliver(cf, `Website enquiry from ${v("name")}`, fields);
    });
  }

  /* Booking request form */
  const bf = $("#booking-form");
  if (bf) {
    const bk = CFG.booking || { open: "09:00", close: "17:00", slot: 60, closedDays: [] };
    const dateIn = $("#b-date");
    const slots = $("#slots");
    const slotHint = $("#slot-hint");
    const pad = (n) => String(n).padStart(2, "0");
    const iso = (d) => `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
    const mins = (s) => { const [h, m] = s.split(":").map(Number); return h * 60 + m; };
    dateIn.min = iso(new Date());
    const renderSlots = () => {
      slots.textContent = "";
      const v = dateIn.value;
      if (!v) { slotHint.textContent = "Choose a date to see time options."; return; }
      const d = new Date(`${v}T00:00:00`);
      if (isNaN(d.getTime())) { slotHint.textContent = "Please enter a valid date."; return; }
      if (v < dateIn.min) { slotHint.textContent = "That date is in the past. Please choose another."; return; }
      if (bk.closedDays.includes(d.getDay())) { slotHint.textContent = "No time options on this day. Please choose another date."; return; }
      const now = new Date();
      const nowMin = now.getHours() * 60 + now.getMinutes();
      let n = 0;
      for (let t = mins(bk.open); t + bk.slot <= mins(bk.close); t += bk.slot) {
        if (v === iso(now) && t <= nowMin) continue;
        const val = `${pad(Math.floor(t / 60))}:${pad(t % 60)}`;
        const wrap = doc.createElement("div");
        wrap.className = "slot";
        const input = doc.createElement("input");
        input.type = "radio"; input.name = "time"; input.value = val; input.id = `slot-${val.replace(":", "")}`;
        const label = doc.createElement("label");
        label.htmlFor = input.id; label.textContent = val;
        wrap.append(input, label);
        slots.append(wrap);
        n += 1;
      }
      slotHint.textContent = n ? "Pick the time you would like. The business will confirm it." : "No more time options today. Please choose another date.";
    };
    dateIn.addEventListener("change", renderSlots);
    dateIn.addEventListener("input", renderSlots);
    renderSlots();
    $$("[data-book-service]").forEach((a) => a.addEventListener("click", () => {
      const sel = bf.elements["service"];
      if (sel) sel.value = a.dataset.bookService;
    }));
    bf.addEventListener("submit", (e) => {
      e.preventDefault();
      clearErrors(bf);
      const v = (n) => (bf.elements[n] && bf.elements[n].value ? bf.elements[n].value.trim() : "");
      const picked = $("input[name=time]:checked", bf);
      const errors = {};
      if (v("name").length < 2) errors.name = "Please enter your name.";
      if (!v("phone") && !v("email")) errors.phone = "Please give a phone number or an email so we can confirm.";
      if (v("email") && !emailOk(v("email"))) errors.email = "That email address does not look right.";
      if (bf.elements["service"] && !v("service")) errors.service = "Please choose an option.";
      if (!dateIn.value) errors.date = "Please choose a date.";
      else if (dateIn.value < dateIn.min) errors.date = "That date is in the past.";
      else if (bk.closedDays.includes(new Date(`${dateIn.value}T00:00:00`).getDay())) errors.date = "No time options on that day.";
      else if (!picked) errors.time = "Please pick a time.";
      if (bf.elements["guests"]) {
        const g = Number(v("guests"));
        if (!Number.isInteger(g) || g < 1 || g > 20) errors.guests = "Enter a number from 1 to 20.";
      }
      if (Object.keys(errors).length) return fail(bf, errors);
      const fields = [["name", "Name", v("name")]];
      if (v("phone")) fields.push(["phone", "Phone", v("phone")]);
      if (v("email")) fields.push(["email", "Email", v("email")]);
      if (v("service")) fields.push(["service", CFG.serviceLabel || "Service", v("service")]);
      if (v("guests")) fields.push(["guests", "Guests", v("guests")]);
      fields.push(["date", "Preferred date", dateIn.value], ["time", "Preferred time", picked.value]);
      if (v("notes")) fields.push(["notes", "Notes", v("notes")]);
      deliver(bf, `Booking request from ${v("name")}`, fields);
    });
  }

  /* Gallery lightbox */
  const dlg = $("#lightbox");
  if (dlg && typeof dlg.showModal === "function") {
    const big = $("#lightbox-img");
    const cap = $("#lightbox-cap");
    $$(".gallery__item").forEach((btn) => btn.addEventListener("click", () => {
      const img = $("img", btn);
      big.src = img.currentSrc || img.src;
      big.alt = img.alt;
      cap.textContent = img.alt;
      dlg.showModal();
    }));
    dlg.addEventListener("click", (e) => { if (e.target === dlg) dlg.close(); });
    $("#lightbox-close").addEventListener("click", () => dlg.close());
  }
})();
